const hasProp = Object.prototype.hasOwnProperty

function throwsMessage(err: any) {
  return '[Throws: ' + (err ? err.message : '?') + ']'
}

function safeGetValueFromPropertyOnObject(obj: any, property: any) {
  if (hasProp.call(obj, property)) {
    try {
      return obj[property]
    } catch (err: any) {
      return throwsMessage(err)
    }
  }

  return obj[property]
}

function ensureProperties(obj1: any) {
  const seen: any[] = [] // store references to objects we have seen before

  function visit(obj: any): any {
    if (obj === null || typeof obj !== 'object') {
      return obj
    }

    if (seen.indexOf(obj) !== -1) {
      return '[Circular]'
    }
    seen.push(obj)

    if (typeof obj.toJSON === 'function') {
      try {
        const fResult = visit(obj.toJSON())
        seen.pop()
        return fResult
      } catch (err: any) {
        return throwsMessage(err)
      }
    }

    if (Array.isArray(obj)) {
      const aResult = obj.map(visit)
      seen.pop()
      return aResult
    }

    const result = Object.keys(obj).reduce(function (acc: any, prop: any) {
      // prevent faulty defined getter properties
      acc[prop] = visit(safeGetValueFromPropertyOnObject(obj, prop))
      return acc
    }, {})
    seen.pop()
    return result
  }

  return visit(obj1)
}

export function safeStringify(data: any, replacer?: any, space?: any) {
  return JSON.stringify(ensureProperties(data), replacer, space)
}
